#pragma once

// Decode the existing *retail-verified* Uniracers/Unirally title picture.
// Source: regional_title_retail_asset.hpp, exact USA/EU captured crop
// 238x81 with source/target digest authority. This lives in the Modern host
// only; it cannot overwrite the original guest, Authentic frame or the retail
// asset generated by the regional presentation project.
#include "regional_title_retail_asset.hpp"

#include <array>
#include <cstddef>
#include <cstdint>

namespace ur::product {
namespace title_retail_reference {
namespace data = ur::product::regional_title_asset;

struct Decoded {
    std::array<std::uint8_t, data::kIndexCount> indices{};
    bool valid = false;
};

inline constexpr char kBase85Alphabet[] =
    "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
    "!#$%&()*+-;<=>?@^_`{|}~";

inline int digit(char c) noexcept {
    for (int i = 0; i < 85; ++i)
        if (kBase85Alphabet[i] == c) return i;
    return -1;
}

template <std::size_t N>
Decoded decode(const char* encoded, const std::array<std::uint32_t, N>& palette,
               std::uint64_t expected_digest) noexcept {
    Decoded result{};
    if (!encoded) return result;
    std::uint64_t digest = 1469598103934665603ull;
    for (std::size_t first = 0; first < data::kIndexCount; first += 4) {
        const std::size_t group = first / 4;
        std::uint64_t packed = 0;
        for (std::size_t i = 0; i < 5; ++i) {
            const int d = digit(encoded[group * 5 + i]);
            if (d < 0) return result;
            packed = packed * 85u + static_cast<unsigned>(d);
        }
        if (packed > 0xffffffffull) return result;
        for (std::size_t slot = 0; slot < 4 &&
             first + slot < data::kIndexCount; ++slot) {
            const auto index = static_cast<std::uint8_t>(
                (packed >> (24 - slot * 8)) & 255u);
            if (index >= palette.size()) return result;
            result.indices[first + slot] = index;
            const std::uint32_t bgr = palette[index];
            for (int shift : {0, 8, 16}) {
                digest ^= (bgr >> shift) & 255u;
                digest *= 1099511628211ull;
            }
        }
    }
    result.valid = digest == expected_digest;
    return result;
}

inline bool paint_retail_title_art(
    std::uint32_t* pixels, int stride, int surface_height,
    int x, int y, bool europe = false) noexcept {
    if (!pixels || stride <= 0 || surface_height <= 0 ||
        x < 0 || y < 0 || x > stride - data::kWidth ||
        y > surface_height - data::kHeight) return false;
    static const Decoded usa = decode(
        data::kSourceIndicesBase85, data::kSourcePalette,
        data::kSourceCropBgrFnv1a64);
    static const Decoded eu = decode(
        data::kIndicesBase85, data::kPalette,
        data::kTargetCropBgrFnv1a64);
    const auto& art = europe ? eu : usa;
    if (!art.valid) return false;
    // Both palette tables store exact original BGR channel triplets packed
    // as 0x00RRGGBB. A fixed opaque alpha creates host painter ARGB.
    if (europe) {
        for (int row = 0; row < data::kHeight; ++row)
            for (int col = 0; col < data::kWidth; ++col)
                pixels[(y + row) * stride + x + col] =
                    0xff000000u | data::kPalette[
                        art.indices[row * data::kWidth + col]];
    } else {
        for (int row = 0; row < data::kHeight; ++row)
            for (int col = 0; col < data::kWidth; ++col)
                pixels[(y + row) * stride + x + col] =
                    0xff000000u | data::kSourcePalette[
                        art.indices[row * data::kWidth + col]];
    }
    return true;
}
} // namespace title_retail_reference
} // namespace ur::product
